-- Synthetic experimentation seed bundle.
PRAGMA foreign_keys = ON;
CREATE TABLE experiments (experiment_id TEXT PRIMARY KEY, name TEXT, hypothesis TEXT, status TEXT, randomization_unit TEXT, allocation_method TEXT, seed TEXT, start_at TEXT, end_at TEXT, analysis_plan_id TEXT, primary_metric_id TEXT, conversion_window_days TEXT, scenario TEXT);
CREATE TABLE variants (variant_id TEXT PRIMARY KEY, experiment_id TEXT, name TEXT, allocation_ratio TEXT, is_control TEXT, effective_from TEXT, effective_to TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id));
CREATE TABLE audience_members (audience_member_id TEXT PRIMARY KEY, experiment_id TEXT, user_id TEXT, eligible_at TEXT, eligibility_status TEXT, segment TEXT, region TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id));
CREATE TABLE assignments (assignment_id TEXT PRIMARY KEY, experiment_id TEXT, audience_member_id TEXT, user_id TEXT, variant_id TEXT, assigned_at TEXT, randomization_seed TEXT, assignment_status TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id), FOREIGN KEY (audience_member_id) REFERENCES audience_members(audience_member_id), FOREIGN KEY (variant_id) REFERENCES variants(variant_id));
CREATE TABLE exposure_events (exposure_id TEXT PRIMARY KEY, experiment_id TEXT, assignment_id TEXT, user_id TEXT, variant_id TEXT, exposed_at TEXT, surface TEXT, telemetry_status TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id), FOREIGN KEY (assignment_id) REFERENCES assignments(assignment_id), FOREIGN KEY (variant_id) REFERENCES variants(variant_id));
CREATE TABLE conversion_events (conversion_id TEXT PRIMARY KEY, experiment_id TEXT, assignment_id TEXT, user_id TEXT, variant_id TEXT, occurred_at TEXT, event_name TEXT, value_usd TEXT, is_primary_conversion TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id), FOREIGN KEY (assignment_id) REFERENCES assignments(assignment_id), FOREIGN KEY (variant_id) REFERENCES variants(variant_id));
CREATE TABLE metric_definitions (metric_id TEXT PRIMARY KEY, experiment_id TEXT, name TEXT, metric_type TEXT, numerator_event TEXT, denominator TEXT, unit TEXT, window_days TEXT, version TEXT, effective_from TEXT, effective_to TEXT, is_primary TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id));
CREATE TABLE guardrail_metrics (guardrail_id TEXT PRIMARY KEY, experiment_id TEXT, metric_id TEXT, name TEXT, direction TEXT, threshold TEXT, unit TEXT, severity TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id), FOREIGN KEY (metric_id) REFERENCES metric_definitions(metric_id));
CREATE TABLE experiment_results (result_id TEXT PRIMARY KEY, experiment_id TEXT, variant_id TEXT, metric_id TEXT, metric_version TEXT, analysis_population TEXT, n_assigned TEXT, n_exposed TEXT, numerator TEXT, denominator TEXT, estimate TEXT, control_estimate TEXT, absolute_effect TEXT, relative_effect TEXT, std_error TEXT, ci95_low TEXT, ci95_high TEXT, p_value TEXT, srm_p_value TEXT, guardrail_status TEXT, decision TEXT, analysis_at TEXT, analysis_plan_id TEXT, FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id), FOREIGN KEY (variant_id) REFERENCES variants(variant_id), FOREIGN KEY (metric_id) REFERENCES metric_definitions(metric_id));
CREATE TABLE ground_truth (issue_id TEXT PRIMARY KEY, issue_type TEXT, entity TEXT, record_id TEXT, ground_truth TEXT, details TEXT);
